def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    opp = [h[1] for h in history]
    my = [h[0] for h in history]

    opp_c = opp.count('C')
    opp_d = n - opp_c
    my_d = my.count('D')

    last_opp = opp[-1]
    last_my = my[-1]
    rounds_left = 100 - n

    # If opponent almost never defects, keep cooperating; only defect in final rounds.
    if opp_d == 0:
        if rounds_left <= 1:
            return 'D'
        return 'C'

    # If opponent is extremely defection-heavy, mostly defect with rare probes.
    if opp_d * 4 >= n * 3:
        if last_opp == 'C' and n >= 3 and opp[-2] == 'C':
            return 'C'
        if n > 20 and rng.random() < 0.05:
            return 'C'
        return 'D'

    # Detect long defection streak by opponent.
    streak = 0
    for a in reversed(opp):
        if a == 'D':
            streak += 1
        else:
            break

    # Long opponent defection streak: punish, but if we've also defected a lot,
    # occasionally offer cooperation to break the DD loop.
    if streak >= 2:
        if streak >= 4 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent defects rarely but just defected: retaliate, with small forgiveness.
    if last_opp == 'D':
        if opp_d <= max(1, n // 8) and rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent cooperated last round.
    # If we defected and opponent still cooperated, they are forgiving; cooperate back
    # most of the time, but exploit mildly if very forgiving and mid-game.
    if last_my == 'D':
        # Count how many times opponent cooperated immediately after our defection.
        forgiving = 0
        chances = 0
        for i in range(1, n):
            if my[i - 1] == 'D':
                chances += 1
                if opp[i] == 'C':
                    forgiving += 1
        if chances >= 2 and forgiving * 2 >= chances:
            # Opponent is quite forgiving. Occasionally exploit.
            if rounds_left > 15 and rng.random() < 0.25:
                return 'D'
        return 'C'

    # Both cooperative last round. Mostly cooperate, occasionally test.
    if rounds_left <= 2:
        return 'D'
    if n >= 8 and rounds_left > 10 and rng.random() < 0.04:
        return 'D'
    return 'C'
